cat > tests/services/zz-scratch-change-lead.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { can, ROLE_MATRIX, PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as projectService from "@/server/services/project-service";
import { NotFoundError, projectResource } from "@/server/services/_support";
import { changeProjectLeadSchema } from "@/schemas/project";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("scratch", () => {
  it("works", async () => {
    const t = await createTenant("lead", "growth");
    const other = await createTenant("leadb", "growth");
    const p = t.project;
    const { owner, admin, member, viewer } = t.actors;
    expect(ROLE_MATRIX["project:change_lead"]).toBe("admin");
    const base = { orgId: t.org.id, projectId: p.id };
    expect(() => changeProjectLeadSchema.parse({ ...base })).toThrow();
    expect(changeProjectLeadSchema.parse({ ...base, leadId: null }).leadId).toBeNull();

    await expect(projectService.changeProjectLead(member, { ...base, leadId: member.userId })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(projectService.changeProjectLead(other.actors.owner, { ...base, leadId: null })).rejects.toBeInstanceOf(TenantScopeError);
    await expect(projectService.changeProjectLead(owner, { ...base, projectId: other.project.id, leadId: null })).rejects.toBeInstanceOf(NotFoundError);
    await expect(projectService.changeProjectLead(admin, { ...base, leadId: viewer.userId })).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(projectService.changeProjectLead(admin, { ...base, leadId: other.actors.member.userId })).rejects.toBeInstanceOf(NotFoundError);
    const r = await projectService.changeProjectLead(admin, { ...base, leadId: member.userId });
    expect(r.leadId).toBe(member.userId);
    expect(can(member, "project:change_lead", projectResource(r))).toBe(true);
    const r2 = await projectService.changeProjectLead(member, { ...base, leadId: owner.userId });
    expect(r2.leadId).toBe(owner.userId);
    const m = await memberRepo.findMember(t.org.id, member.userId);
    await memberRepo.archiveMember(t.org.id, m!.id);
    await expect(projectService.changeProjectLead(owner, { ...base, leadId: member.userId })).rejects.toBeInstanceOf(NotFoundError);
    await projectRepo.archiveProject(t.org.id, p.id);
    await expect(projectService.changeProjectLead(owner, { ...base, leadId: null })).rejects.toBeInstanceOf(AlreadyArchivedError);
    expect((await projectRepo.findProjectById(t.org.id, p.id))!.leadId).toBe(owner.userId);
  });
});
EOF
